class Solution:
    def searchRange(self, nums: List[int], target: int) -> List[int]:
        n = len(nums)
        first, last = n, n

        low, high = 0, n - 1
        # find the first pos
        while low <= high:
            mid = (low + high) // 2
            if nums[mid] >= target:
                first = mid
                high = mid - 1
            else:
                low = mid + 1

        low, high = 0, n - 1
        # find the idx after last pos
        while low <= high:
            mid = (low + high) // 2
            if nums[mid] > target:
                last = mid
                high = mid - 1
            else:
                low = mid + 1

        last -= 1

        return [first, last] if first <= last else [-1,-1]
